-- Field: Invoices.IsOverdue
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_invoices_is_overdue(p_invoice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(NOT (COALESCE(calc_invoices_is_paid(p_invoice_id), FALSE)), FALSE) AND COALESCE(COALESCE((calc_invoices_days_past_due(p_invoice_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_invoices_status
-- Field: Invoices.Status
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_invoices_status(p_invoice_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_invoices_is_paid(p_invoice_id) THEN ('Paid')::text ELSE (CASE WHEN calc_invoices_is_overdue(p_invoice_id) THEN ('Overdue')::text ELSE ('Open')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_sessions_client_name
-- Field: Sessions.ClientName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: FullName from related Clients

CREATE OR REPLACE FUNCTION calc_sessions_client_name(p_session_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT full_name::text FROM clients WHERE client_id = (SELECT client FROM sessions WHERE session_id = p_session_id));
$$ LANGUAGE sql STABLE;

