-- Lookup: TrainerHourlyRate from related Clients

CREATE OR REPLACE FUNCTION calc_sessions_client_hourly_rate(p_session_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_clients_trainer_hourly_rate((SELECT client FROM sessions WHERE session_id = p_session_id));
